use xiom.io;

use xiom.math;
type Point = {
  x: Float64;
  y: Float64;
}

fn Point.distance_to(self, other: Point) -> Float64 {
  let dx = x - other.x;
  let dy = y - other.y;
  return math.sqrt(dx * dx + dy * dy);
}

fn main() -> Int {
  let a = Point{ x: 1.0, y: 2.0 };
  let b = Point{ x: 4.0, y: 6.0 };
  let dist = a.distance_to(b);
  io.println(dist.to_str());
  return 0;
}
